1	/**
2	 * third-party-actions.ts — Typed wrappers for third-party actions we use
3	 * that aren't (yet) in the public `@github-actions-workflow-ts/actions`
4	 * registry.
5	 */
6	import { CustomAction, type StepBaseProps } from "./base.ts";
7	
8	export interface SetupBunInputs {
9	  "bun-version"?: string;
10	}
11	
12	/**
13	 * Pinned, and not "latest", on purpose. `latest` makes every run resolve and
14	 * download the current release from the GitHub CDN before anything can start,
15	 * and when the CDN blips (HTTP 504, seen twice on 2026-11-08) every machinery
16	 * workflow fails with it -- entry, runs, deploy, PR close, the watch sweep. A
17	 * pin is cacheable by setup-bun, so one successful download serves the rest,
18	 * and the version moves only when somebody moves it here.
19	 */
20	const BUN_VERSION = "1.4.2";
21	
22	export class SetupBunAction extends CustomAction<SetupBunInputs> {
23	  constructor(props: StepBaseProps & { with?: SetupBunInputs } = {}) {
24	    super("oven-sh/setup-bun@v2", { ...props, with: { "bun-version": BUN_VERSION, ...props.with } });
25	  }
26	}

