599	export function threadHold(events: readonly TurnEvent[], openClaim: { ask: number; run: number } | undefined): ThreadHold {
600	  const newest = events[events.length - 1];
601	  if (openClaim !== undefined) {
602	    return newest === "waiting" ? { kind: "parked" } : { kind: "in-flight" };
